"""Small robust client for the local order service.

Handles: expiring tokens (401/403 -> fetch a new one), rate limiting (429 -> wait the
time the service asks for), transient failures (5xx, network errors, malformed or
structurally wrong bodies -> repeat the request). Every non-200 response is logged.
"""
import datetime
import email.utils
import json
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"


def _now():
    return datetime.datetime.now(datetime.timezone.utc)


class Client:
    def __init__(self, logf):
        self.logf = logf
        self.token = None
        self.stats = {"requests": 0, "tokens": 0, "status": {}, "waits": [], "unknown_wait": 0}

    def log(self, *parts):
        ts = _now().strftime("%H:%M:%S.%f")[:-3]
        print(ts, *parts, file=self.logf, flush=True)

    def _count(self, key):
        self.stats["status"][key] = self.stats["status"].get(key, 0) + 1

    def _raw(self, method, path, auth):
        self.stats["requests"] += 1
        req = urllib.request.Request(BASE + path, method=method,
                                     data=(b"" if method == "POST" else None))
        if auth:
            req.add_header("Authorization", f"Bearer {self.token}")
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, {k.lower(): v for k, v in r.headers.items()}, r.read()
        except urllib.error.HTTPError as e:
            try:
                body = e.read()
            except Exception:
                body = b""
            return e.code, {k.lower(): v for k, v in (e.headers or {}).items()}, body
        except Exception as e:  # connection reset, timeout, incomplete read...
            return None, {}, repr(e).encode()

    def _retry_after(self, headers, body):
        v = headers.get("retry-after")
        if v is not None:
            v = v.strip()
            try:
                return float(v)
            except ValueError:
                try:
                    dt = email.utils.parsedate_to_datetime(v)
                    return max(0.0, (dt - _now()).total_seconds())
                except Exception:
                    pass
        try:
            j = json.loads(body)
            if isinstance(j, dict):
                for k in ("retry_after", "retry_after_seconds", "retryAfter", "wait", "wait_seconds"):
                    if k in j:
                        return float(j[k])
        except Exception:
            pass
        return None

    def _wait_429(self, headers, body, path):
        wait = self._retry_after(headers, body)
        if wait is None:
            self.stats["unknown_wait"] += 1
            self.log("NO-RETRY-HINT", path, "falling back to 5s")
            wait = 5.0
        self.stats["waits"].append(wait)
        time.sleep(wait + 0.05)

    def new_token(self):
        fails = 0
        while True:
            status, headers, body = self._raw("POST", "/token", auth=False)
            self._count(f"token:{status}")
            if status == 200:
                try:
                    t = json.loads(body)["token"]
                    if isinstance(t, str) and t:
                        self.token = t
                        self.stats["tokens"] += 1
                        self.log("TOKEN", t)
                        return
                except Exception:
                    pass
                self.log("TOKEN-BAD-BODY", repr(body[:300]))
            else:
                self.log("TOKEN-HTTP", status, json.dumps(headers), repr(body[:300]))
            if status == 429:
                self._wait_429(headers, body, "/token")
                continue
            fails += 1
            if fails > 40:
                raise RuntimeError("could not obtain a token")
            time.sleep(min(5.0, 0.5 * fails))

