        """GET path until a valid 200 (or a status in ok_statuses) comes back.

        Returns (status, parsed_json_or_None, raw_body).
        """
        fails = 0
        auth_fails = 0
        while True:
            if self.token is None:
                self.new_token()
            status, headers, body = self._raw("GET", path, auth=True)
            self._count(str(status))
            if status == 200:
                try:
                    j = json.loads(body)
                except Exception:
                    self.log("BAD-JSON", path, json.dumps(headers), repr(body[:300]))
                    j = None
                problem = "unparseable" if j is None else validate(j)
                if not problem:
                    return 200, j, body
                self.log("INVALID-200", path, problem, repr(body[:300]))
            else:
                self.log("HTTP", status, path, json.dumps(headers), repr(body[:300]))
                if status in ok_statuses:
                    return status, None, body
                if status in (401, 403):
                    auth_fails += 1
                    if auth_fails > 10:
                        raise RuntimeError(f"auth keeps failing on {path}")
                    self.new_token()
                    continue
                if status == 429:
                    self._wait_429(headers, body, path)
                    continue
            fails += 1
            if fails > 40:
                raise RuntimeError(f"giving up on {path} after {fails} failures")
            time.sleep(min(5.0, 0.5 * fails))

