"""Fetch every order page by following "next" from page 1. Saves raw bodies.

usage: python3 -I fetch_pages.py OUTDIR
"""
import json
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from client import Client  # noqa: E402

ITEM_KEYS = ("id", "customer_id", "status", "placed_at", "amount_cents")


def page_validator(expected):
    def v(j):
        if not isinstance(j, dict):
            return "not an object"
        for k in ("page", "total_pages", "items", "next"):
            if k not in j:
                return f"missing {k}"
        if j["page"] != expected:
            return f"page is {j['page']!r}, expected {expected}"
        if not isinstance(j["total_pages"], int):
            return "total_pages not int"
        if not isinstance(j["items"], list):
            return "items not a list"
        if j["next"] is not None and not isinstance(j["next"], str):
            return "next neither null nor string"
        for it in j["items"]:
            if not isinstance(it, dict):
                return "item not an object"
            missing = [k for k in ITEM_KEYS if k not in it]
            if missing:
                return f"item missing {missing}"
        return None
    return v


def main():
    outdir = sys.argv[1]
    os.makedirs(outdir, exist_ok=True)
    logf = open(os.path.join(outdir, "fetch.log"), "a")
    c = Client(logf)
    path, expected = "/orders?page=1", 1
    seen_pages, total_pages_values, nexts = [], set(), {}
    while path is not None:
        m = re.fullmatch(r"/orders\?page=(\d+)", path)
        if not m:
            raise RuntimeError(f"unexpected next path {path!r}")
        expected = int(m.group(1))
        if expected in seen_pages:
            raise RuntimeError(f"next loops back to page {expected}")
        _, j, body = c.get_json(path, page_validator(expected))
        with open(os.path.join(outdir, f"page_{expected:03d}.json"), "wb") as f:
            f.write(body)
        seen_pages.append(expected)
        total_pages_values.add(j["total_pages"])
        nexts[expected] = j["next"]
        print(f"page {expected}: {len(j['items'])} items, next={j['next']}", flush=True)
        path = j["next"]
    summary = {"pages": seen_pages, "total_pages_values": sorted(total_pages_values),
               "nexts": nexts, "stats": c.stats}
    with open(os.path.join(outdir, "summary.json"), "w") as f:
        json.dump(summary, f, indent=1)
    print(json.dumps({k: v for k, v in summary.items() if k != "nexts"}))


if __name__ == "__main__":
    main()

