import datetime
import glob
import json
import os
import sys

UTC = datetime.timezone.utc
START = datetime.datetime(2025, 3, 1, tzinfo=UTC)   # inclusive
END = datetime.datetime(2025, 6, 1, tzinfo=UTC)     # exclusive (i.e. through 31 May 23:59:59.999...)


def to_utc(ts):
    dt = datetime.datetime.fromisoformat(ts)
    if dt.tzinfo is None:
        raise ValueError(f"timestamp without offset: {ts!r}")
