"""Fetch each needed customer exactly once (cached on disk).

usage: python3 -I fetch_customers.py SELECTION.json OUTDIR
"""
import json
import os
import sys
import time

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from client import Client  # noqa: E402

KEYS = ("id", "name", "region", "tier", "discount_pct")


def customer_validator(cid):
    def v(j):
        if not isinstance(j, dict):
            return "not an object"
        missing = [k for k in KEYS if k not in j]
        if missing:
            return f"missing {missing}"
        if j["id"] != cid:
            return f"id is {j['id']!r}, expected {cid!r}"
        return None
    return v


def main():
    sel, outdir = sys.argv[1], sys.argv[2]
    os.makedirs(outdir, exist_ok=True)
    cache_fn = os.path.join(outdir, "customers.json")
    cache = json.load(open(cache_fn)) if os.path.exists(cache_fn) else {}
    logf = open(os.path.join(outdir, "fetch.log"), "a")
    c = Client(logf)
    ids = json.load(open(sel))["customer_ids"]
    for cid in ids:
        if cid in cache:
            continue
        status, j, body = c.get_json(f"/customers/{cid}", customer_validator(cid), ok_statuses=(404,))
        if status == 404:
            # confirm it is a stable "unknown id" and not a transient failure
            confirmations = []
            for _ in range(3):
                time.sleep(1)
                c.new_token()
                s2, j2, _ = c.get_json(f"/customers/{cid}", customer_validator(cid), ok_statuses=(404,))
                confirmations.append(s2)
                if s2 == 200:
                    j = j2
                    break
            if j is None:
                cache[cid] = {"_status": 404, "_confirmations": confirmations}
            else:
                cache[cid] = j
        else:
            cache[cid] = j
        json.dump(cache, open(cache_fn, "w"), indent=1)
    print(json.dumps({"customers": len(cache), "stats": c.stats}))


if __name__ == "__main__":
    main()

